  // ═══ SUN (ರವಿ) ═══
  static const sunInSign = <int, String>{
    0: 'ಶಾಸ್ತ್ರಾರ್ಥ ಕೃತಿ ಕಲಾಭಿಃ ಖ್ಯಾತೋ ಯುದ್ಧ ಪ್ರಿಯಃ ಪ್ರಚಂಡಶ್ಚ\nಉದ್ಯುಕ್ತೋ ಭ್ರಮಣರುಚಿರ್ಥೃಡಾಸ್ಥಿಬಂಧಃ ಕ್ರಿಯೋ ಷ್ರೇಷ್ಠಃ\nಸಾಹಸ ಕರ್ಮಾಭಿರತಃ ಪಿತ್ತ ಸೃಗ್ವ್ಯಾಧಿಕಾಂತಿ ಸತ್ವಯುತಃ\nಸೂರ್ಯೇ ಭವತಿ ನರೇಂದ್ರಃ ಸ್ವತಂಗರಾಶೌ ನರೋ ಜಾತಃ',
    1: 'ವದನಾಕ್ಷಿ ರೋಗ ತಪ್ತಃ ಕ್ಲೇಷ ಸಹಿಷ್ಣು ರ್ನಚಾಪಿ ಬಹುಶತ್ರುಃ\nಭಕ್ತೌ ವ್ಯವಹಾರರತೌ ಮತಿಮಾನ್ ವಂಧ್ಯಾಂಗನಾ ದ್ವೇಷಿ\nಭೋಜನಮಾಲ್ಯಾಚ್ಛಾದನ ಗಂಧಯುತೋ ಗೇಯವಾದ್ಯ ನೃತ್ಯಜ್ಞಃ\nದಿವಸಕರೇ ವೃಷಸಂಸ್ಥೇ ಭವತಿ ಪುಮಾನ್ ಸಲಿಲ ಭೀರುಶ್ಚ',
    2: 'ಮೇಧಾವೀ ವಾಂಗ್ಮದುರೋ ವಾತ್ಸಲ್ಯ ಗುಣೈರ್ಯುತಃ ಶ್ರುತಾಚಾರಃ\nವಿಜ್ಞಾನಶಾಸ್ತ್ರ ಕುಷಲೋ ಬಹುವಿತ್ತ ಉದಾರ ಜೇಷ್ಟಶ್ಚ\nನಿಪುಣೋ ಜ್ಯೋತಿಷವೇತ್ತಾ ಮಧ್ಯಮರೂಪೋ ದ್ವಿಮಾತೃಕಃ ಸುಭಗಃ\nಮಿಥುನಸ್ಥೋ ದಿನಭರ್ತರಿ ಜಾತಃ ಪುರುಷೋ ವಿನೀತಃ ಸ್ಯಾತ್',
    3: 'ಕರ್ಮಸುಚಪಲಃ ಖ್ಯಾತೋ ಗುಣೈರ್ನಪಾಣಾಂ ಸ್ವಪಕ್ಷವಿದ್ವೇಷಿ\nಸ್ಟೀದುರ್ಭಗಃ ಸುರೂಪಃ ಕಫ ಪಿತ್ತಾರ್ಥಃ ಶ್ರಮಾಭಿಸಂತಪ್ತಃ\nಮಧ್ಯರುಚಿಃ ಸಮಧರ್ಮಾ ಪರವಾಕ್ಯದೇಶ ದಿಗ್ದೇವತಾ\nಸೂರ್ಯ ಕುಲೀರ ಸಂಸ್ಥೆ ಬಹುಸ್ಥಿತಿಃ ಪಿತೃಗಣದ್ವೇಷ್ಟಾ',
    4: 'ರಿಪುಹಂತಾ ಕ್ರೋಧಪರೋ ವಿಷಿಷ್ಟಚೇಶ್ಟೋ ವನಾದ್ರಿ ದುರ್ಗಚರಃ\nಉತ್ಸಾಹಿ ಸಚ್ಚೂರತೇಜಸ್ವೀ ಮಾಂಸಭಕ್ಷಣೋ ರೌದ್ರಃ\nಗಂಭೀರಃ ಸ್ಥಿರ ಸತ್ವೋ ಬಧಿರಃ ಕ್ಷಿತಿಪಾಲಕೋ ಧನಸಮೃದ್ಧಃ\nಸಿಂಹಸ್ಥೋ ದಿವಸಕರೇ ಖ್ಯಾತಃ ಪುರುಷೋ ಭವೇಜ್ಞಾತಃ',
    5: 'ಸ್ತ್ರೀತುಲ್ಯಹನುಹ್ರೀಮಾನ್ ಲಿಪಿವೇತ್ತಾ ದುರ್ಬಲಶ್ಚ ವಲ್ಗುಕಥಃ\nಮೇಧಾವೀ ಲಘುಸತ್ವೋ ವಿದ್ವಾನ್ ಶುಶ್ರೂಷಕಃ ಸುರಗುರೂಣಾಂ\nಸಂವಾಹನಾದಿ ಕರ್ಮಸು ದಕ್ಷಃ ಶ್ರುತಿಗೇಯವಾದ್ಯಪರಿತುಷ್ಟಃ\nಕನ್ಯಾಯಾಂ ದಿವಸಕರೆ ಜಾತೋ ಮೃದುದೀನ ವಾಕ್ಯಶ್ಚ',
    6: 'ಭಂಗಕ್ಷಯ ವೈಯಾರ್ಥೋ ವಿದೇಶಮಾರ್ಗಾದಿ ಲಂಪಟೋ ದ್ವಿಷ್ಟಃ\nನೀಚೋಪಹತಪ್ರೀತಿರ್ಹಿರಣ್ಯ ಲೋಹಾದಿ ಪಣ್ಯಜೀವಿ\nದ್ವೇಷ್ಯಃ ಪರ ಕರ್ಮರತಃ ಪರದಾರರತಿಃ ಪುಮಾನ್ ಭವೇನ್ಮಲಿನಃ\nಸೂರ್ಯೆ ತುಲಾಧರಸ್ಥೇ ನೃಪಪರಿಭೂತಃ ಪ್ರಗಲ್ಭಶ್ಚ',
    7: 'ಅನಿವಾರಿತರಣವೇಗಃ ಶೃತಿಧರ್ಮರತೋ ನಸತ್ಯ ವಾಂಗ್ಮೂರ್ಖಃ\nಪ್ರವಿನಷ್ಟದುಷ್ಟಯುವತಿಃ ಕ್ರೂರಃ ಕುಸ್ತ್ರೀವಿಧೇಯಶ್ಚ\nಕ್ರೋಧಪರೋ ಅಸದ್ವ್ರತ್ತೊ ಲೋಭಿಷ್ಟಃ ಕಲಹವಲ್ಲಭೂ ಅನೃತವಾಕ್\nಶಸ್ತ್ರಾಗ್ನಿವಿಷಗ್ರಸ್ಥಃ ಪಿತುರ್ಜನನ್ಯಾಶ್ಚ ದುರ್ಭಗಃ ಕೀಟೇ',
    8: 'ದ್ರವ್ಯಾನ್ವಿತೋ ನೃಪೇಷ್ಟೊ ಜಾತಃ ಪ್ರಾಜ್ಞಃ ಸುರದ್ವಿಜಾನುರತಃ\nಶಸ್ತ್ರಾಸ್ತ್ರಹಸ್ತಿಶಿಕ್ಷಾನಿಪುಣಃ ವ್ಯವಹಾರ ಯೋಗ್ಯಶ್ಚ\nಪೂಜ್ಯಃ ಸತಾಂ ಪ್ರಶಾಂತೋ ಧನವಾನ್ ವಿಸ್ತೀರ್ಣ ಪೀನಚಾರುತನುಃ\nಬಂಧೂನಾಂ ಹಿತಕಾರೀ ಸತ್ವಯುತಃ ಕಾರ್ಮುಕೋ ಸೂರ್ಯೇ',
    9: 'ಲುಬ್ಧಃ ಕುಸ್ತ್ರೀಸಕ್ತಃ ಕುಕರ್ಮ ಸಂವರ್ಧಿತಃ ಸತೃಷ್ಣಶ್ಚ\nಬಹುಕಾರ್ಯರತೋ ಭೀರುರ್ವಿಹೀನಬಂಧುಶ್ಚಲಪ್ರಕೃತಿಃ\nಅಟನಪ್ರಿಯೋsಲ್ಪಸತ್ವಃ ಸ್ವಪಕ್ಷವಿಕ್ಷೋಭನಾಶಿತಸಮಸ್ತಃ\nಮಕರಸ್ತೊ ದಿವಸಕರೇ ಜಾತೋ ಬಹುಭಕ್ಷಕಃ ಪುರುಷಃ',
    10: 'ಹೃದ್ರೋಗಿ ಬಹು ಸತ್ವಃ ಸತಾಂ  ವಿಗೃಹ್ಯೋ ಅತಿರೋಷಶ್ಚ\nಪರದಾರಾಣಾಂ ಸುಭಗಃ ಕರ್ಮಸ್ವತಿನಿಶ್ಚಿತೋ ಭವತಿ\nದುಃಖಪ್ರಾಯೋ ಅಲ್ಪಧನಃ ಶಟಶ್ಚಲಿತ ಸೌಹೃದೋ ಮಲಿನ ಮೂರ್ತಿಃ\nಕುಂಬಧರೋ ಅರ್ಕೇ ಜಾತಃ ಪಿಶುನಃ ಸ್ಯಾತ್ ದುಷ್ಟ್ರಲಾಪಶ್ಚ',
    11: 'ಸುಹೃದಾಂ ಸಂಗ್ರಹಶೀಲಃ ಸ್ತ್ರೀಪ್ರಿತ್ಯಾ ಲಭ್ದಸೌಖ್ಯಸಂಭಾರಃ\nಪ್ರಾಜ್ಞೋ ಬಹುಶತ್ರುಘ್ನಃ ಕ್ಷಯೋ ಯದಿಭವತಿ ಧನಕೀರ್ತ್ಯಾ\nಸತ್ಸುತ ಭೃತ್ಯಾಪ್ತಯಶಾ ಜಲಪಣ್ಯಧನಃ ಸುವಾಗನೃತವಾದಿ\nಊರ್ಜಿತಗುಹ್ಯರೋಗಾರ್ತೊ ಬಹುಸಹಜೋ ಮೀನ ಸಂಸ್ಥೆ ಅರ್ಕೇ',
