  static const moonInSign = <int, String>{
    0: 'ಸೌವರ್ಣಾಂಗಃ ಸ್ಥಿರಸ್ವಃ ಸಹಜ ವಿರಹಿತಃ ಸಾಹಸೀ ಮಾನಭದ್ರಃ\nಕಾಮಾರ್ತಃ ಕ್ಷಾಮಜಾನುಃ ಕುನಖ ತನುಕಚಶ್ಚಂಚಲೋ ಮಾನವಿತ್ತಃ\nಪದ್ಮಾಭೈಃ ಪಾಣಿಪಾದೈಃರ್ವಿತತಸುತಜನೋ ವರ್ತುಲಾಕಾರನೇತ್ರಃ\nಸಸ್ನೇಹಸ್ತೋಯಬೀರುರ್ವ್ರಣವಿಕೃತಶಿರಾಃ ಸ್ತ್ರೀಜಿತೋ ಮೇಷ ಇಂದೌ',
    1: 'ವ್ಯುಡೊರಸ್ಕೊSದಾತಾಧನ ಕುಟಿಲಕಚಃ ಕಾಮುಕಃ ಕೀರ್ತಿಶಾಲಿ\nಕಾಂತಃ ಕನ್ಯಾಪ್ರಜಾವಾನ್ ವೃಷಸಮನಯನೋ ಹಂಸಲೀಲಾಪ್ರಚಾರಃ\nಮಧ್ಯಾಂತೋ ಭೋಗಭಾಗೀ ಪೃಥುಕಟಿಚರಣಸ್ಕಂಧಜಾನ್ವಾಸ್ಯಜಂಗಃ\nಸಾಂಕಃ ಪಾರ್ಷ್ಟಸ್ಯಪೃಷ್ಠೆ ಕಕುದಿ ಶುಭಗತಿಃ ಕ್ಷಾಂತಿಯುಕ್ತೊ ಗವೀಂದೌ',
    2: 'ಉನ್ನಾಸಶ್ಯಾಮಚಕ್ಷುಃ ಸುರತವಿಧಿ ಕಲಾಕಾವ್ಯಕೃಬ್ಧೊಗಬೋಗಿ\nಹಸ್ತೇ ಮತ್ಸ್ಯಾಧಿಪಾಂಕೋ ವಿಷಯಸುಖರತೋ ವ್ಯಾಯತಾಂಗೋ\nಯಾತಿ ಕ್ಲೀಭೈಶ್ಚ ಸಂಖ್ಯಂ ಶಶಿನಿ ಮಿಥುನಗೋ ಮಾತೃಯುಗ್ಮಪ್ರಪುಷ್ಟಃ',
    3: 'ಯುಕ್ತಃ ಸೌಭಾಗ್ಯ ಯೋಗ್ಯೆರ್ಗೃಹ ಸುಹೃದಟನಜ್ಯೋತಿಷ ಜ್ಞಾನಶೀಲೈಃ\nಕಾಮಾಸಕ್ತಃ ಕೃತಜ್ಞಃ ಕ್ಷಿತಿಪತಿಸಜೀವಃ ಸತ್ಪ್ರಮಾಣಃ ಪ್ರವಾಸೀ\nಸೋನ್ಮಾದಃ ಕೇಶಕಲ್ಪೋ ಜಲಕುಸುಮ ರುಚಿರ್ಹಾನಿವೃದ್ಧಾನುಯಾತಃ\nಪ್ರಾಸಾದೋ ಧ್ಯಾನವಾಪಿಪ್ರಿಯಕರಣರತಃ ಪೀನಕಂಠಃ ಕುಲೀರೇ',
    4: 'ಸ್ಥೂಲಾಸ್ಥಿರ್ಮಂದರೋಮಾ ಪೃಥುವದನಗಲೋ ಹ್ರಸ್ವಪಿಂಗಾಕ್ಷಿಯುಗ್ಮಃ\nಸ್ತ್ರೀದ್ವೇಷೀ ಕ್ಷುತ್ಪಿಪಾಸಾಜಠರರದರುಜಾ ಪೀಡಿತೋ ಮಾಂಸಭಕ್ಷಃ\nದಾತಾ ತೀಕ್ಷ್ಣೋ ಹ್ಯಪುತ್ರೋ ವಿಪಿನನಗರತಿರ್ಮಾತೃವಶ್ಯಃ ಸುವಕ್ಷಾಃ\nವಿಕ್ರಾಂತಃ ಕಾರ್ಯಲಾಪೀ ಶಶಭೃತಿ ರವಿಭೇ ಸರ್ವಗಂಭೀರದೃಷ್ಟಿಃ',
    5: 'ಸ್ತ್ರೀಲೋಲೋ ಲಂಬಬಾಹುರ್ಲಲಿತತನುಮುಖಶ್ಚಾರುದಂತಾಕ್ಷಿಕರ್ಣೋ\nವಿದ್ವಾನಾಚಾರ್ಯಧರ್ಮಾ ಪ್ರಿಯವಚನಯುತಃ ಸತ್ಯಶೌಚಪ್ರಧಾನಃ\nಧೀರಃ ಸತ್ವಾನುಕಂಪೀ ಪರವಿಷಯರತಃ ಕ್ಷಾಂತಿಸೌಭಾಗ್ಯಭಾಗೀ\nಕನ್ಯಾಪ್ರಾಯಪ್ರಸೂತಿರ್ಬಹುಸುತರಹಿತಃ ಕನ್ಯಕಾಯಾಂ ಶಶಾಂಕೇ',
    6: 'ಉನ್ನಾಸೋ ವ್ಯಾಯತಾಕ್ಷಃ ಕೃಶವದನತನುರ್ಭೂರಿದಾರೋ ವೃಷಾಢ್ಯೋ\nಗೋಭೂಮ್ಯಃ ಶೌಚಸಾರೋ ವೃಷಸಮವೃಷಣೋ ವಿಕ್ರಮಜ್ಞಃ ಕ್ರಿಯೇಶಃ\nಭಕ್ತೋ ದೇವದ್ವಿಜಾನಾಂ ಬಹುವಿಭವಯುತಃ ಸ್ತ್ರೀಜಿತೋ ಹೀನದೇಹೋ\nಧಾನ್ಯಾದಾನೈಕಬುದ್ಧಿಸ್ತುಲಿನಿ ಶಶಧರೇ ಬಂಧುವರ್ಗೋಪಕಾರೀ',
    7: 'ಲುಬ್ಧೋ ವೃತ್ತೋರುಜಂಘಃ ಕಠಿನತರತನುರ್ನಾಸ್ತಿಕಃ ಕ್ರೂರಚೇಷ್ಟಃ\nಚೋರೋ ಬಾಲ್ಯೇ ರುಗಾರ್ತೋ ಹತಚಿಬುಕನಖಶ್ಚಾರುನೇತ್ರಃ ಸಮೃದ್ಧಃ\nಕರ್ಮೋದ್ಯುಕ್ತಃ ಪ್ರದಕ್ಷಃ ಪರಯುವತಿರತೋ ಬಂಧುಹೀನಃ ಪ್ರಮತ್ತಃ\nಚಂಡೋ ರಾಜ್ಞಾ ಹತಸ್ವಃ ಪೃಥುಜಠರಶಿರಾಃ ಕೀಟಭೇ ಶೀತರಶ್ಮೌ',
