  /// Get Saravali rashi phala for a planet in a given rashi index (0-11).
  static String getPhala(String planetEng, int rashiIdx) {
    const dataMap = {
      'Sun': sunInSign,
      'Moon': moonInSign,
      'Mars': marsInSign,
      'Mercury': mercuryInSign,
      'Jupiter': jupiterInSign,
      'Venus': venusInSign,
      'Saturn': saturnInSign,
    };
    return dataMap[planetEng]?[rashiIdx] ?? '';
  }
